func (q *Queries) ListAvailableServices(ctx context.Context, arg ListAvailableServicesParams) ([]ListAvailableServicesRow, error) {
	rows, err := q.db.Query(ctx, listAvailableServices,
		arg.IdentityID,
		arg.ControlSessionID,
		arg.Now,
		arg.AfterID,
		arg.AccessPath,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListAvailableServicesRow
	for rows.Next() {
		var i ListAvailableServicesRow
		if err := rows.Scan(
			&i.ID,
			&i.TeamID,
			&i.TeamName,
			&i.Name,
			&i.CreatedAt,
			&i.Protocol,
			&i.PublisherPool,
			&i.TrustRevision,
			&i.RequirePostQuantum,
			&i.CertificateHostname,
			&i.ServicePort,
			&i.Public,
			&i.ServiceRunID,
			&i.RunNumber,
			&i.VisitorAccess,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

